        self._done = []
        self._undone = []
        self._depth = 0
        self._group = None

    def text(self):
        return self._text

    def begin_group(self):
        self._depth += 1
        if self._depth == 1:
            self._group = []

    def end_group(self):
        if self._depth == 0:
            return
        self._depth -= 1
        if self._depth == 0:
            if self._group:
                self._done.append(self._group)
            self._group = None

    def _apply(self, edit):
        kind, pos, s = edit
        if kind == 'insert':
            self._text = self._text[:pos] + s + self._text[pos:]
        else:
            self._text = self._text[:pos] + self._text[pos + len(s):]

    @staticmethod
    def _invert(edit):
        kind, pos, s = edit
        return ('delete' if kind == 'insert' else 'insert', pos, s)

    def _record(self, edit):
        if self._depth > 0:
            self._group.append(edit)
        else:
            self._done.append([edit])
        self._undone.clear()

    def insert(self, pos, s):
        if pos < 0 or pos > len(self._text):
            raise IndexError(pos)
        edit = ('insert', pos, s)
        self._apply(edit)
        self._record(edit)

