        if n < 0:
            raise IndexError(pos)
        edit = ('delete', pos, self._text[pos:pos + n])
        self._apply(edit)
        self._record(edit)

    def undo(self):
        if self._depth > 0:
            raise RuntimeError('group is open')
        if not self._done:
            return
        step = self._done.pop()
        for edit in reversed(step):
            self._apply(self._invert(edit))
        self._undone.append(step)

